function add(a, b) {
  return a + b;
}

// 1. 학습 및 최적화 (Optimizing)
for (let i = 0; i < 10000; i++) {
  add(i, i);
}
// -> 엔진 판단: "이 함수는 (Int, Int) 입력만 받는구나!" -> 기계어 컴파일 완료

// 2. 타입 변경 (Deoptimization 유발!)
add('Hello', 'World');
// -> 엔진 당황: "어? 문자열이네?" 
// -> 기계어 폐기 및 인터프리터 모드로 복귀 (느려짐)
